// spec: .qa/e2e/specs/emergency.md
// seed: tests/seed.user.spec.ts
import { test, expect } from '@playwright/test';
import path from 'node:path';

test.use({ storageState: path.join(__dirname, '../../../auth/user.json') });

test.describe('Звонок 101 с экрана «עזרה דחופה»', () => {
  test('Сбой открытия tel: → «לא ניתן לחייג מהמכשיר הזה» / «חייגו 101 מטלפון אחר.» #1273694f @iphone @prod-safe', async ({ page }) => {
    // 1. До загрузки страницы подменить открытие tel: так, чтобы оно падало.
    // Сайт открывает tel: через Linking.openURL -> window.location = 'tel:101' (не бросает исключение),
    // поэтому сбой вызывается в единственном месте, где openURL может отклониться: конструктор URL бросает для tel:.
    // Навигация на tel: на всякий случай отменяется.
    await page.addInitScript(() => {
      const w = window as any;
      w.__telCalls = [];
      w.navigation?.addEventListener('navigate', (e: any) => {
        if (String(e.destination.url).startsWith('tel:')) {
          w.__telCalls.push(e.destination.url);
          if (e.cancelable) e.preventDefault();
        }
      });
      const OriginalURL = window.URL;
      window.URL = new Proxy(OriginalURL, {
        construct(target, args, newTarget) {
          if (String(args[0]).startsWith('tel:')) throw new TypeError('tel: blocked by test');
          return Reflect.construct(target, args, newTarget);
        },
      });
    });
    const dialogs: string[] = [];
    page.on('dialog', async (dialog) => {
      dialogs.push(dialog.message());
      await dialog.accept();
    });

    // 2. Открыть /emergency → «חיוג למד״א 101» → «חיוג ל-101».
    await page.goto('/emergency');
    await page.getByRole('button', { name: 'חיוג למד״א 101' }).click();
    await expect(page.getByRole('heading', { name: 'לחייג למד״א 101?' })).toBeVisible();
    await page.getByRole('button', { name: 'חיוג ל-101' }).click();

    // Ожидаемое: показан браузерный dialog с обеими строками.
    await expect.poll(() => dialogs.length).toBe(1);
    expect(dialogs[0]).toContain('לא ניתן לחייג מהמכשיר הזה');
    expect(dialogs[0]).toContain('חייגו 101 מטלפון אחר.');

    // 3. Закрыть сообщение (dialog.accept() в обработчике) — страница /emergency на месте.
    await expect(page).toHaveURL(/\/emergency$/);
    await expect(page.getByRole('heading', { name: 'עזרה דחופה' })).toBeVisible();
    await expect(page.getByRole('heading', { name: 'לחייג למד״א 101?' })).toBeHidden();
  });
});
